-- Bonus buys: pre-played bought bonuses (same engines as the games). price = the cost in stakes; mean(total)/price = the return (~96%).
create table if not exists buy_seeds (game text not null, kind text not null, id int not null, seed bigint not null, total numeric not null, primary key (game, kind, id));
create table if not exists buy_prices (game text not null, kind text not null, price int not null, primary key (game, kind));
alter table buy_seeds enable row level security; alter table buy_prices enable row level security; revoke all on buy_seeds, buy_prices from anon, authenticated;
delete from buy_seeds where game in ('kinneret','wild_west'); delete from buy_prices where game in ('kinneret','wild_west','pachinko','fortune');
